 int localProxyPort;
 void LoadPreview(){var group=new SubscriptionGroup{Name="Design review · offline fixture",Url="https://example.invalid/sub/preview",Updated=DateTime.UtcNow,TotalBytes=100L*1024*1024*1024,UsedBytes=72L*1024*1024*1024,ExpiresUnix=DateTimeOffset.UtcNow.AddDays(28).ToUnixTimeSeconds()};foreach(var item in new[]{("🇩🇪 Frankfurt · Edge 01","vless"),("🇳🇱 Amsterdam · Edge 02","vmess"),("🇫🇮 Helsinki · Edge 03","wireguard")})group.Profiles.Add(new JsonObject{["remarks"]=item.Item1,["outbounds"]=new JsonArray(new JsonObject{["protocol"]=item.Item2,["settings"]=new JsonObject{["vnext"]=new JsonArray(new JsonObject{["address"]="example.invalid",["port"]=443})},["streamSettings"]=new JsonObject{["network"]="tcp",["security"]="reality"}})});subscriptions.Add(group);groups.Items.Add(group);groups.SelectedIndex=0;status.Text=L("Offline preview · Sample data", "پیش‌نمایش آفلاین · داده‌های نمایشی");add.Enabled=false;refresh.Enabled=false;UpdateSelectedSummary();BeginInvoke(new Action(()=>File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"layout.txt"),new[]{"dpi="+DeviceDpi+" form="+Size+" scale="+AutoScaleDimensions,"title="+stateTitle.Bounds+" font="+stateTitle.Font.Height+" parent="+stateTitle.Parent!.Size,"hint="+stateHint.Bounds+" font="+stateHint.Font.Height,"summary="+serverSummary.Bounds+" font="+serverSummary.Font.Height})));}
 async Task RefreshIp(){if(xray==null||busy)return;try{using var handler=new HttpClientHandler{UseProxy=box==null};if(box==null)handler.Proxy=new WebProxy($"socks5://127.0.0.1:{localProxyPort}");using var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(8)};var content=await http.GetStringAsync("https://www.cloudflare.com/cdn-cgi/trace");var address=content.Split('\n').FirstOrDefault(line=>line.StartsWith("ip="))?[3..].Trim();if(xray!=null&&IPAddress.TryParse(address,out _))Metric("ip",address!);}catch{Metric("ip","ناموجود");}}
